import React, { useState } from "react";

const QuizPage = () => {
  const [formData, setFormData] = useState({
    exam: "",
    difficultyLevels: [],
    classYear: "",
    name: "",
    quizMode: "",
    addHints: false,
    answerExplanation: false,
    breakIntoSubtopics: false,
    subjects: [],
    topics: [],
    currentSubject: "",
    currentTopic: "",
    numberOfQuestions: null,
  });

  const [timerOption, setTimerOption] = useState("noTimer");
  const [perQuestionTime, setPerQuestionTime] = useState("");
  const [totalTime, setTotalTime] = useState("");

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setFormData((prevData) => ({
      ...prevData,
      [name]: type === "checkbox" ? checked : value,
    }));
  };

  const handleDifficultyChange = (e) => {
    const { value, checked } = e.target;
    setFormData((prevData) => ({
      ...prevData,
      difficultyLevels: checked
        ? [...prevData.difficultyLevels, value]
        : prevData.difficultyLevels.filter((level) => level !== value),
    }));
  };

  const handleSubmit = (event) => {
    event.preventDefault();
    console.log(formData);
  };

  const handleAddSubject = () => {
    if (formData.currentSubject.trim()) {
      setFormData((prev) => ({
        ...prev,
        subjects: [...prev.subjects, formData.currentSubject.trim()],
        currentSubject: "",
      }));
    }
  };

  const handleAddTopic = () => {
    if (formData.currentTopic.trim()) {
      setFormData((prev) => ({
        ...prev,
        topics: [...prev.topics, formData.currentTopic.trim()],
        currentTopic: "",
      }));
    }
  };

  const handleTimerChange = (e) => {
    setTimerOption(e.target.value);
    setPerQuestionTime("");
    setTotalTime("");
  };

  return (
    <div className="min-h-screen bg-gray-100 p-6 sm:p-10">
      <div className="max-w-4xl mx-auto bg-white p-6 rounded-lg shadow-lg">
        <h1 className="text-2xl font-semibold text-center text-blue-600 mb-6">
          Create Your Quiz
        </h1>
        <form onSubmit={handleSubmit} className="space-y-6">
          <section>
            <h2 className="text-lg font-semibold text-gray-700 mb-2">Personal Details</h2>
            <input
              type="text"
              placeholder="What should we call you? (e.g., ABC XYZ)"
              name="name"
              value={formData.name}
              onChange={handleChange}
              className="w-full p-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-blue-400"
              required
            />
          </section>

          <section>
            <h2 className="text-lg font-semibold text-gray-700 mb-2">Exam Details</h2>
            <div className="space-y-4">
              <input
                type="text"
                placeholder="Exam Type (e.g., Midterm, JEE)"
                name="exam"
                value={formData.exam}
                onChange={handleChange}
                className="w-full p-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-blue-400"
                required
              />
              <input
                type="number"
                placeholder="Number of Questions (e.g., 5, 10)"
                name="numberOfQuestions"
                value={formData.numberOfQuestions}
                onChange={handleChange}
                className="w-full p-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-blue-400"
                required
              />
            </div>
          </section>

          <section>
            <h2 className="text-lg font-semibold text-gray-700 mb-2">Difficulty Levels</h2>
            <div className="flex items-center gap-4">
              {["Easy", "Medium", "Hard"].map((level) => (
                <label key={level} className="flex items-center gap-2">
                  <input
                    type="checkbox"
                    value={level}
                    checked={formData.difficultyLevels.includes(level)}
                    onChange={handleDifficultyChange}
                    className="form-checkbox rounded border-gray-300"
                  />
                  {level}
                </label>
              ))}
            </div>
          </section>

          <section>
            <h2 className="text-lg font-semibold text-gray-700 mb-2">Additional Features</h2>
            <div className="space-y-4">
              {[
                { name: "addHints", label: "Add Hints" },
                { name: "answerExplanation", label: "Include Answer Explanation" },
                { name: "breakIntoSubtopics", label: "Break into Subtopics" },
              ].map((feature) => (
                <label key={feature.name} className="flex items-center gap-2">
                  <input
                    type="checkbox"
                    name={feature.name}
                    checked={formData[feature.name]}
                    onChange={handleChange}
                    className="form-checkbox rounded border-gray-300"
                  />
                  {feature.label}
                </label>
              ))}
            </div>
          </section>

          <section>
            <h2 className="text-lg font-semibold text-gray-700 mb-2">Subjects & Topics</h2>
            <div className="space-y-4">
              <div>
                <input
                  type="text"
                  name="currentSubject"
                  value={formData.currentSubject}
                  onChange={(e) =>
                    setFormData({ ...formData, currentSubject: e.target.value })
                  }
                  placeholder="Enter Subject"
                  className="w-full p-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-blue-400"
                />
                <button
                  type="button"
                  onClick={handleAddSubject}
                  className="mt-2 px-4 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700"
                >
                  Add Subject
                </button>
              </div>

              <div>
                <input
                  type="text"
                  name="currentTopic"
                  value={formData.currentTopic}
                  onChange={(e) =>
                    setFormData({ ...formData, currentTopic: e.target.value })
                  }
                  placeholder="Enter Topic"
                  className="w-full p-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-green-400"
                />
                <button
                  type="button"
                  onClick={handleAddTopic}
                  className="mt-2 px-4 py-2 bg-green-500 text-white rounded-md hover:bg-green-600"
                >
                  Add Topic
                </button>
              </div>
            </div>
          </section>

          <section>
            <h2 className="text-lg font-semibold text-gray-700 mb-2">Timer Options</h2>
            <div className="space-y-2">
              {["noTimer", "perQuestion", "totalTime"].map((option) => (
                <label key={option} className="flex items-center gap-2">
                  <input
                    type="radio"
                    name="timerOption"
                    value={option}
                    checked={timerOption === option}
                    onChange={handleTimerChange}
                    className="form-radio text-blue-600"
                  />
                  {option === "noTimer"
                    ? "No Timer"
                    : option === "perQuestion"
                    ? "Set Time per Question"
                    : "Set Total Time for Quiz"}
                </label>
              ))}
            </div>
          </section>

          <button
            type="submit"
            className="w-full py-2 bg-blue-600 text-white text-lg font-medium rounded-lg hover:bg-blue-700"
          >
            Create Quiz
          </button>
        </form>
      </div>
    </div>
  );
};

export default QuizPage;
